function verifyUnion({requireCompletion=false}={}){const f=frozen(),meta=read(path.join(container,'continuation.meta.json'));assert.deepEqual(fs.readdirSync(container).sort(),['run','contexts','continuation.meta.json',...['completion.json','failure.json'].filter(x=>fs.existsSync(path.join(container,x)))].sort(),'unexpected continuation container inventory');approve(meta.scope.approval,f);assert.equal(meta.scope.freeze_sha256,f.freeze_sha256);assert.equal(meta.scope.base_snapshot_sha256,f.own.base_snapshot_sha256);assert.deepEqual(meta.original_history,f.old.history);assert.equal(meta.old_freeze_sha256,f.old.f.freeze_sha256);assert.equal(meta.target_count,2453);assert.equal(meta.first_target,RETRY_TARGET);const config={binding:f.old.f.binding,targets:f.old.suffix,scope:meta.scope,owner:meta.owner},v=store.verify(run,config),suffix=[];let failedContext=null;const allRefs=[];
 for(let i=0;i<v.count;i++){const target=f.old.suffix[i],x=require('./attempt.cjs').verifyContext({container,run,contexts,i,target,explicit_recollection:f.own.explicit_recollection,binding:f.old.f.binding,load:()=>v.load(i)});allRefs.push(...x.files);if(x.credited)suffix.push({target,valid:true,context_complete:true});else{assert.equal(i,v.count-1,'records after failed context');failedContext={new_seq:i,original_plan_index:331+i,target_id:target.id,native_data_returned:x.end.native_data_returned,error:x.end.error};}}
 assert.deepEqual(fs.readdirSync(contexts).sort(),allRefs.sort(),'orphan/partial context evidence');const union=reconcile(f.old.f.plan,f.old.prefix,suffix,f.old.history);if(failedContext)assert.equal(union.complete,false);const summary={...union,new_attempts:v.count,new_failed_context:failedContext,old_last_hash:OLD_LAST,new_last_hash:v.last_hash,source_font_dependency_binding_sha256:e.digest(f.old.f.binding),freeze_sha256:f.freeze_sha256,original_pass_count:331+v.original_pass_count,original_false_count:v.original_false_count,browser_started:false,native_started:false};if(requireCompletion&&union.complete){assert.equal(fs.existsSync(path.join(container,'failure.json')),false);assert.deepEqual(read(path.join(container,'completion.json')),{schema:1,...summary,source_after:f.old.f.binding.receipts});}return summary;}
